function lowerBound(i) { return i[0]; }
function upperBound(i) { return i[1]; }
function addInterval(x, y) {
  return makeInterval(lowerBound(x) + lowerBound(y), upperBound(x) + upperBound(y));
}

const r1 = makeInterval(6, 6.25);
const r2 = makeInterval(4.5, 4.75);
console.log(addInterval(r1, r2));

